# Bible People cards — plain, everyday English.
# Each person: id, name, role (one line), art (scene id or None), facts (3 short tags),
# cards [(heading, text)], read [(book, chapter, label)]  (Douay-Rheims book names / numbering)
CATS = []
def cat(key, title, blurb, art, people): CATS.append({"key":key, "title":title, "blurb":blurb, "art":art, "people":people})

cat("twelve", "The 12 Disciples", "The ordinary men Jesus picked to change the world.", "last-supper", [
 dict(id="peter", name="Peter", role="Fisherman who became the leader of the apostles", art="peter-denies",
  facts=["Also called Simon", "Brother of Andrew", "Wrote 1 & 2 Peter"],
  cards=[
   ("Who he was", "Simon was a fisherman on the Sea of Galilee, working the boats with his brother Andrew. Jesus gave him a new name, Peter, which means “rock.”"),
   ("Bold and loud", "Peter was usually the first to speak. He stepped out of the boat to walk on water toward Jesus, then panicked and started to sink. When Jesus asked, “Who do you say I am?”, Peter answered: “You are the Messiah, the Son of the living God.”"),
   ("His worst night", "Peter swore he would never leave Jesus. That same night, after Jesus was arrested, Peter said three times that he didn’t even know Him. A rooster crowed, Jesus looked at him, and Peter went outside and cried."),
   ("A second chance", "After rising from the dead, Jesus met Peter on the beach and asked him three times, “Do you love me?” — one for each denial. Each time Jesus told him, “Take care of my sheep.”"),
   ("What happened next", "Weeks later Peter preached in Jerusalem and about 3,000 people believed in one day. He led the early church, healed people, and was thrown in prison more than once. Church tradition says he was crucified in Rome — upside down, because he didn’t feel worthy to die the same way as Jesus."),
   ("Why it matters", "Peter’s biggest failure wasn’t the end of his story. Jesus restored him and built His church on him."),
  ], read=[("Matthew",14,"Walking on water"),("Matthew",16,"“You are the Messiah”"),("Luke",22,"Peter’s denial"),("John",21,"“Do you love me?”"),("Acts",2,"Peter preaches")]),
 dict(id="andrew", name="Andrew", role="The first disciple — the one who brought people to Jesus", art="fishers",
  facts=["Peter’s brother", "Fisherman", "Was a follower of John the Baptist"],
  cards=[
   ("Who he was", "Andrew was a fisherman and Peter’s brother. Before he met Jesus, he followed John the Baptist."),
   ("The first one", "When John pointed at Jesus and said, “Look, the Lamb of God,” Andrew followed Jesus and spent the day with Him. The very first thing he did after was find his brother and say, “We found the Messiah!”"),
   ("The boy with the lunch", "When 5,000 hungry people needed food, Andrew was the one who found a boy with five small loaves and two fish. Jesus used that little lunch to feed everyone."),
   ("How it ended", "Church tradition says Andrew preached in Greece and was crucified on an X-shaped cross. That X is now called St. Andrew’s cross and is on Scotland’s flag."),
   ("Why it matters", "Andrew was never the star — he was the one who kept bringing other people to Jesus."),
  ], read=[("John",1,"Andrew meets Jesus"),("John",6,"The boy’s lunch")]),
 dict(id="james-zebedee", name="James", role="One of Jesus’ three closest friends — and the first apostle to die for Him", art="transfiguration",
  facts=["Son of Zebedee", "Brother of John", "“Son of Thunder”"],
  cards=[
   ("Who he was", "James and his brother John were fishermen working with their father, Zebedee. When Jesus called them, they left the boat — and their dad — right there."),
   ("Sons of Thunder", "Jesus nicknamed James and John “Sons of Thunder.” When a village refused to welcome Jesus, they asked if they should call fire down from heaven on it. Jesus told them no."),
   ("The inner circle", "James was one of only three disciples Jesus took with Him to see a dead girl raised to life, to see Him shine with glory on the mountain, and to pray with Him in the garden the night before He died."),
   ("How it ended", "Around ten years after Jesus rose, King Herod had James killed with a sword. He was the first of the twelve apostles to die for his faith."),
   ("Why it matters", "James once asked Jesus for a seat of honor. Jesus asked if he could drink the same cup of suffering — and James did."),
  ], read=[("Mark",1,"Called from the boats"),("Mark",10,"Asking for the best seats"),("Acts",12,"James is killed")]),
 dict(id="john", name="John", role="“The disciple Jesus loved” — wrote the Gospel of John", art="patmos",
  facts=["Brother of James", "Took care of Mary", "Wrote 5 books of the Bible"],
  cards=[
   ("Who he was", "John was a young fisherman, the brother of James. In his own Gospel he never uses his name — he calls himself “the disciple Jesus loved.”"),
   ("At the cross", "When almost everyone else ran away, John stood at the foot of the cross. Jesus, dying, looked at His mother Mary and at John and said, “Here is your son… here is your mother.” From then on John took Mary into his home."),
   ("Easter morning", "When Mary Magdalene said the tomb was empty, John and Peter ran there. John got there first, looked in, saw the empty grave clothes, and believed."),
   ("What he wrote", "John wrote the Gospel of John and three short letters. The Book of Revelation was written by a John exiled on the island of Patmos — traditionally the same John."),
   ("How it ended", "Church tradition says John was the only one of the twelve not killed for his faith. He lived to be very old in Ephesus, still telling people: “Little children, love one another.”"),
  ], read=[("John",19,"At the cross"),("John",20,"The empty tomb"),("1 John",4,"“God is love”"),("Revelation",1,"John on Patmos")]),
 dict(id="philip", name="Philip", role="The disciple who said “Come and see”", art="multitude",
  facts=["From Bethsaida", "Brought Nathanael", "Practical thinker"],
  cards=[
   ("Who he was", "Philip came from the same fishing town as Peter and Andrew. Jesus found him and simply said, “Follow me.”"),
   ("Come and see", "Philip ran to tell his friend Nathanael they had found the one Moses wrote about — Jesus of Nazareth. When Nathanael scoffed, Philip didn’t argue. He just said, “Come and see.”"),
   ("Doing the math", "Before feeding the 5,000, Jesus tested Philip: “Where can we buy bread for all these people?” Philip did the numbers — eight months’ wages wouldn’t be enough. Jesus already knew what He was going to do."),
   ("Show us the Father", "At the Last Supper Philip asked, “Lord, show us the Father, and that will be enough.” Jesus answered, “Anyone who has seen me has seen the Father.”"),
   ("How it ended", "Church tradition says Philip preached in what is now Turkey and died as a martyr in the city of Hierapolis."),
  ], read=[("John",1,"“Come and see”"),("John",6,"Feeding the 5,000"),("John",14,"“Show us the Father”")]),
 dict(id="bartholomew", name="Bartholomew (Nathanael)", role="The skeptic Jesus saw under the fig tree", art="sermon",
  facts=["Probably also called Nathanael", "Friend of Philip", "Honest to a fault"],
  cards=[
   ("Who he was", "Bartholomew is listed among the twelve in Matthew, Mark and Luke. Most scholars think he is the same man John’s Gospel calls Nathanael, because he is always paired with Philip."),
   ("Nazareth? Really?", "When Philip told him the Messiah was from Nazareth, Nathanael said, “Can anything good come from Nazareth?” It was a small, unimpressive town."),
   ("Seen before he knew it", "As he walked up, Jesus said, “Here is a true Israelite — nothing fake about him.” Nathanael asked how Jesus knew him. “I saw you under the fig tree before Philip called you.” Nathanael was stunned: “You are the Son of God!”"),
   ("How it ended", "He was one of the disciples fishing when the risen Jesus appeared on the shore. Church tradition says he later preached as far as India and Armenia and died as a martyr."),
   ("Why it matters", "Jesus didn’t mind Nathanael’s honest doubts. He met him right where he was."),
  ], read=[("John",1,"Under the fig tree"),("John",21,"Breakfast with the risen Jesus")]),
 dict(id="thomas", name="Thomas", role="“Doubting Thomas” — who ended up with the boldest confession", art=None,
  facts=["Called “the Twin”", "Brave and blunt", "Tradition: took the gospel to India"],
  cards=[
   ("Who he was", "Thomas was also called Didymus, which means “the Twin.” We don’t know who his twin was."),
   ("Braver than you think", "When Jesus decided to go back near Jerusalem, where people wanted to kill Him, Thomas said to the others: “Let’s go too, so we can die with Him.”"),
   ("Honest questions", "When Jesus said, “You know the way to where I’m going,” Thomas said what everyone was thinking: “We don’t know where you’re going — how can we know the way?” Jesus answered, “I am the way, the truth and the life.”"),
   ("The doubt", "Thomas wasn’t there when the risen Jesus first appeared. He said he wouldn’t believe unless he could touch the nail wounds. A week later Jesus showed up and said, “Go ahead — touch them.” Thomas fell down and said, “My Lord and my God!”"),
   ("How it ended", "Church tradition says Thomas traveled all the way to India, started churches there, and was killed with a spear near today’s Chennai. Christians in India still call themselves St. Thomas Christians."),
  ], read=[("John",11,"“Let’s go die with Him”"),("John",14,"“I am the way”"),("John",20,"“My Lord and my God!”")]),
 dict(id="matthew", name="Matthew", role="Tax collector who walked away from the money", art="tribute",
  facts=["Also called Levi", "Worked for Rome", "Wrote the Gospel of Matthew"],
  cards=[
   ("Who he was", "Matthew, also called Levi, collected taxes in Capernaum for the Roman government. Tax collectors often overcharged and kept the extra, so people saw them as traitors and thieves."),
   ("Follow me", "Jesus walked past Matthew’s tax booth and said two words: “Follow me.” Matthew got up, left the money on the table, and went."),
   ("The party", "Matthew threw a big dinner for Jesus and invited his tax-collector friends. The religious leaders were disgusted. Jesus said, “Healthy people don’t need a doctor — sick people do. I came for sinners.”"),
   ("What he wrote", "The first book of the New Testament, the Gospel of Matthew, has been credited to him since the earliest days of the church. It’s full of the Old Testament promises Jesus fulfilled."),
   ("Why it matters", "Nobody was too far gone for Jesus — not even the most hated guy in town."),
  ], read=[("Matthew",9,"Matthew is called"),("Luke",5,"Matthew’s party")]),
 dict(id="james-alphaeus", name="James, son of Alphaeus", role="The quiet apostle", art=None,
  facts=["Sometimes called “James the Less”", "Name in every list of the 12", "Almost nothing else is known"],
  cards=[
   ("Who he was", "This James is named in every list of the twelve apostles, but the Bible tells us almost nothing else about him. He’s called the son of Alphaeus to tell him apart from James the brother of John."),
   ("James the Less", "He may be the “James the younger” mentioned at the cross. “The Less” probably meant younger or shorter, not less important."),
   ("Faithful in the background", "He was there for all of it — the miracles, the Last Supper, the cross, the empty tomb and Pentecost — without one recorded speech or story."),
   ("Why it matters", "Most people who follow Jesus will never be famous. James shows that the quiet ones are chosen too."),
  ], read=[("Mark",3,"Jesus names the twelve"),("Acts",1,"In the upper room")]),
 dict(id="jude-thaddaeus", name="Jude (Thaddaeus)", role="The apostle who asked one great question", art=None,
  facts=["Also called Thaddaeus", "Not Judas Iscariot", "Saint of “lost causes”"],
  cards=[
   ("Who he was", "Two lists call him Thaddaeus; Luke calls him Judas, son of James. John makes sure to add “not Judas Iscariot” so nobody mixes them up."),
   ("His question", "At the Last Supper he asked Jesus: “Why are you showing yourself to us and not to the whole world?” Jesus answered that He and the Father would come and live with anyone who loves Him."),
   ("How it ended", "Church tradition says he preached in Mesopotamia and Persia alongside Simon the Zealot, and they died as martyrs there."),
   ("Why it matters", "Today many Catholics pray to St. Jude for hopeless situations — a reminder that no case is too lost for God."),
  ], read=[("John",14,"Jude’s question"),("Luke",6,"The twelve are chosen")]),
 dict(id="simon-zealot", name="Simon the Zealot", role="A rebel who ended up on the same team as a tax collector", art=None,
  facts=["Called “the Zealot”", "Possibly anti-Rome", "Little else is known"],
  cards=[
   ("Who he was", "Simon is always called “the Zealot” to tell him apart from Simon Peter. Zealots were Jews who wanted to drive the Romans out, sometimes by force."),
   ("An unlikely team", "Think about it: Jesus put Simon, who hated Rome, on the same team as Matthew, who worked for Rome. Following Jesus made them brothers."),
   ("How it ended", "The Bible doesn’t say. Church tradition says Simon preached with Jude in Persia and died there."),
   ("Why it matters", "Jesus brings together people who would never choose each other."),
  ], read=[("Luke",6,"The twelve are chosen"),("Acts",1,"Waiting for the Spirit")]),
 dict(id="judas", name="Judas Iscariot", role="The disciple who betrayed Jesus", art="judas-kiss",
  facts=["Kept the money bag", "30 pieces of silver", "Betrayed Jesus with a kiss"],
  cards=[
   ("Who he was", "Judas was one of the twelve. He saw every miracle and heard every teaching. He was trusted with the group’s money."),
   ("The money", "John’s Gospel says Judas was a thief who helped himself from the money bag. When a woman poured expensive perfume on Jesus, Judas complained it should have been sold — not because he cared about the poor."),
   ("The deal", "Judas went to the chief priests and asked, “What will you give me if I hand Him over?” They paid him 30 pieces of silver — the price of a slave."),
   ("The kiss", "In the garden at night Judas led soldiers to Jesus. His signal was a kiss on the cheek. Jesus said, “Judas, are you betraying me with a kiss?”"),
   ("How it ended", "When Jesus was condemned, Judas was filled with regret. He threw the money back at the priests and went out and hanged himself. The priests used the money to buy a field to bury strangers."),
   ("Why it matters", "Peter and Judas both failed Jesus the same night. Peter came back and was forgiven. Judas gave up. It’s never too late to come back."),
  ], read=[("John",12,"The perfume"),("Matthew",26,"30 pieces of silver"),("Matthew",27,"Judas’s end")]),
 dict(id="matthias", name="Matthias", role="Chosen to replace Judas", art=None,
  facts=["The 13th apostle", "Picked by drawing lots", "Followed Jesus from the start"],
  cards=[
   ("Who he was", "Matthias wasn’t one of the original twelve, but he had followed Jesus the whole time — from John’s baptism to the day Jesus went up to heaven."),
   ("Chosen", "After Judas died, the apostles prayed and drew lots between two men, Joseph and Matthias. The lot fell to Matthias, and he became one of the twelve."),
   ("Why it matters", "Matthias stayed faithful for years without a title. When the time came, God used him."),
  ], read=[("Acts",1,"Matthias is chosen")]),
])
